mapper.insert:
INSERT INTO lifecycle_scenario (
    user_id, scenario_name, description, base_date, status
) VALUES (
    #{scenario.userId}, #{scenario.scenarioName},
    #{scenario.description}, #{scenario.baseDate}, #{scenario.status}
)

mapper.update:
UPDATE lifecycle_scenario
SET
    scenario_name = #{scenarioName},
    description = #{description},
    status = #{status}
WHERE lifecycle_scenario_id = #{scenarioId}
  AND user_id = #{userId}
  AND status != 'ARCHIVED'

UPDATE lifecycle_scenario
SET status = 'ARCHIVED'
WHERE lifecycle_scenario_id = #{scenarioId}
  AND user_id = #{userId}
  AND status != 'ARCHIVED'

UPDATE lifecycle_scenario
SET result_data = CAST(#{resultJson} AS JSON),
    status = 'COMPLETED'
WHERE lifecycle_scenario_id = #{scenarioId}
  AND user_id = #{userId}

mapper.select:
SELECT result_data
FROM lifecycle_scenario
WHERE lifecycle_scenario_id = #{scenarioId}
  AND user_id = #{userId}
